using UnityEngine;
using UnityEngine.Rendering;
namespace LWS.TruckBowling {
public sealed class BowlingCabCamera:MonoBehaviour {
 public Camera view;public BowlingLane lane;public Renderer[] exterior,interior;public float Impact;float yaw;bool shotSpectator;public bool ShotSpectator=>shotSpectator;
 public bool Spectating=>lane!=null&&(lane.highlights!=null&&lane.highlights.Playing||shotSpectator||lane.match.AllAI&&!LWS.TruckSports.SportsCameraOptions.ShowAI);
 void OnEnable(){RenderPipelineManager.beginCameraRendering+=Begin;RenderPipelineManager.endCameraRendering+=End;}
 void OnDisable(){RenderPipelineManager.beginCameraRendering-=Begin;RenderPipelineManager.endCameraRendering-=End;Restore();}
 void Begin(ScriptableRenderContext context,Camera camera){var highlights=lane!=null?lane.highlights:null;bool replaying=highlights!=null&&highlights.Playing;bool spectator=Spectating;if(exterior!=null)foreach(var r in exterior)if(r!=null)r.forceRenderingOff=camera==view&&(!spectator||replaying);if(interior!=null)foreach(var r in interior)if(r!=null)r.forceRenderingOff=camera!=view||spectator;if(highlights!=null)highlights.HideLivePins(camera==view&&replaying);}

 void End(ScriptableRenderContext context,Camera camera){Restore();}void Restore(){if(lane!=null&&lane.highlights!=null)lane.highlights.HideLivePins(false);if(exterior!=null)foreach(var r in exterior)if(r!=null)r.forceRenderingOff=false;if(interior!=null)foreach(var r in interior)if(r!=null)r.forceRenderingOff=false;}
 public void ResetView(){shotSpectator=false;if(lane!=null&&lane.truck!=null)yaw=lane.truck.transform.eulerAngles.y;Impact=0;}
 void LateUpdate(){if(lane==null||!view.enabled)return;if(lane.highlights!=null&&lane.highlights.Playing){lane.highlights.ReplayCamera(transform,Time.deltaTime);return;}bool reduced=lane.match.setup.reducedMotion;var body=lane.truck.body;
 if(!shotSpectator&&lane.match.InMatch&&(lane.Phase==BowlingPhase.Settling||lane.Committed&&lane.LegalPinContact&&(lane.truck.ControlLost||lane.truck.Speed<1.5f||lane.Furthest>=lane.pinLine+1.2f)))shotSpectator=true;
 if(shotSpectator){Vector3 focus=new Vector3(lane.center,.6f,lane.pinLine+1);int count=0;Vector3 sum=Vector3.zero;foreach(var pin in lane.pins)if(pin.gameObject.activeSelf){sum+=pin.body.position;count++;}if(count>0){var mean=sum/count;focus.x=Mathf.Clamp(mean.x,lane.center-2,lane.center+2);focus.z=Mathf.Clamp(mean.z,lane.pinLine-1,lane.pinLine+5);}var position=new Vector3(lane.center+2.9f,4.8f,lane.pinLine-5.5f);float blend=1-Mathf.Exp(-Time.deltaTime*3);transform.position=Vector3.Lerp(transform.position,position,blend);transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(focus-transform.position,Vector3.up),blend);return;}
 if(Spectating){var p=body.position;float deck=Mathf.InverseLerp(lane.pinLine-10,lane.pinLine+3,p.z);var focus=Vector3.Lerp(p+Vector3.forward*4,new Vector3(lane.center,.8f,lane.pinLine+2),deck);var position=Vector3.Lerp(p+new Vector3(2.8f,4,-7),new Vector3(lane.center+1.8f,5,lane.pinLine-5),deck);transform.SetPositionAndRotation(position,Quaternion.LookRotation(focus-position,Vector3.up));return;}float target=body.rotation.eulerAngles.y;yaw=Mathf.MoveTowardsAngle(yaw,target,(reduced?180:540)*Time.deltaTime);Impact=Mathf.MoveTowards(Impact,0,Time.deltaTime*.12f);float shake=Impact*(reduced?.12f:1)*Mathf.Sin(Time.time*43);transform.position=body.position+Vector3.up*.43f+body.rotation*Vector3.forward*.05f+Vector3.up*shake;transform.rotation=Quaternion.Euler(1,yaw,0);}
}
}